-- 0001_initial.sql — CouplesCash schema (PLAN.md §5)
-- Primary keys are UUID v7 generated by the API (Guid.CreateVersion7()).
-- Enum-like columns are text + CHECK so Dapper can map them to C# enums by name.

CREATE EXTENSION IF NOT EXISTS citext;

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS users (
    id            uuid        PRIMARY KEY,
    email         citext      NOT NULL,
    display_name  text        NOT NULL,
    password_hash text        NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_email_key UNIQUE (email)
);

CREATE TABLE IF NOT EXISTS households (
    id         uuid        PRIMARY KEY,
    name       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS household_members (
    household_id uuid        NOT NULL REFERENCES households (id) ON DELETE CASCADE,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    joined_at    timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (household_id, user_id),
    -- A user belongs to at most one household.
    CONSTRAINT household_members_user_id_key UNIQUE (user_id)
);

CREATE INDEX IF NOT EXISTS household_members_household_id_idx ON household_members (household_id);

-- A household has at most two members. The household row is locked first so
-- two concurrent joins cannot both pass the count check.
CREATE OR REPLACE FUNCTION enforce_household_member_limit() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM households WHERE id = NEW.household_id FOR UPDATE;
    IF (SELECT count(*) FROM household_members WHERE household_id = NEW.household_id) >= 2 THEN
        RAISE EXCEPTION 'household_full'
            USING ERRCODE = 'check_violation',
                  DETAIL  = 'A household can have at most two members.';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS household_members_limit ON household_members;
CREATE TRIGGER household_members_limit
    BEFORE INSERT ON household_members
    FOR EACH ROW EXECUTE FUNCTION enforce_household_member_limit();

-- Couple codes: 20 random bytes. Both sha256(bytes) (QR payload) and
-- sha256(8-char typed code) are stored so either form can be redeemed.
CREATE TABLE IF NOT EXISTS couple_codes (
    id           uuid        PRIMARY KEY,
    household_id uuid        NOT NULL REFERENCES households (id) ON DELETE CASCADE,
    created_by   uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    code_hash    bytea       NOT NULL,
    payload_hash bytea       NOT NULL,
    expires_at   timestamptz NOT NULL,
    redeemed_at  timestamptz NULL,
    redeemed_by  uuid        NULL REFERENCES users (id) ON DELETE SET NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT couple_codes_code_hash_key    UNIQUE (code_hash),
    CONSTRAINT couple_codes_payload_hash_key UNIQUE (payload_hash)
);

CREATE INDEX IF NOT EXISTS couple_codes_household_id_idx ON couple_codes (household_id);
CREATE INDEX IF NOT EXISTS couple_codes_created_by_idx   ON couple_codes (created_by);
-- Fast path for "is there a live code for this household": only unredeemed rows.
CREATE INDEX IF NOT EXISTS couple_codes_live_idx ON couple_codes (household_id, expires_at) WHERE redeemed_at IS NULL;

CREATE TABLE IF NOT EXISTS refresh_tokens (
    id         uuid        PRIMARY KEY,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash bytea       NOT NULL,
    family_id  uuid        NOT NULL,
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz NULL,
    user_agent text        NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT refresh_tokens_token_hash_key UNIQUE (token_hash)
);

CREATE INDEX IF NOT EXISTS refresh_tokens_user_id_idx   ON refresh_tokens (user_id);
CREATE INDEX IF NOT EXISTS refresh_tokens_family_id_idx ON refresh_tokens (family_id);

-- ---------------------------------------------------------------------------
-- Household data
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS categories (
    id           uuid    PRIMARY KEY,
    household_id uuid    NOT NULL REFERENCES households (id) ON DELETE CASCADE,
    name         text    NOT NULL,
    color        text    NOT NULL,
    icon         text    NOT NULL,
    sort_order   integer NOT NULL DEFAULT 0,
    is_default   boolean NOT NULL DEFAULT false
);

CREATE INDEX IF NOT EXISTS categories_household_id_idx ON categories (household_id);

CREATE TABLE IF NOT EXISTS accounts (
    id            uuid        PRIMARY KEY,
    household_id  uuid        NOT NULL REFERENCES households (id) ON DELETE CASCADE,
    name          text        NOT NULL,
    institution   text        NOT NULL,
    type          text        NOT NULL CHECK (type IN ('checking', 'savings', 'credit', 'cash', 'investment', 'loan')),
    balance_cents bigint      NOT NULL DEFAULT 0,
    color         text        NOT NULL,
    icon          text        NOT NULL,
    note          text        NULL,
    created_by    uuid        NOT NULL REFERENCES users (id),
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    archived_at   timestamptz NULL
);

CREATE INDEX IF NOT EXISTS accounts_household_id_idx     ON accounts (household_id);
CREATE INDEX IF NOT EXISTS accounts_household_active_idx ON accounts (household_id) WHERE archived_at IS NULL;
CREATE INDEX IF NOT EXISTS accounts_created_by_idx       ON accounts (created_by);

CREATE TABLE IF NOT EXISTS account_balance_snapshots (
    id            uuid        PRIMARY KEY,
    account_id    uuid        NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    balance_cents bigint      NOT NULL,
    recorded_at   timestamptz NOT NULL DEFAULT now(),
    recorded_by   uuid        NOT NULL REFERENCES users (id)
);

CREATE INDEX IF NOT EXISTS account_balance_snapshots_account_idx     ON account_balance_snapshots (account_id, recorded_at DESC);
CREATE INDEX IF NOT EXISTS account_balance_snapshots_recorded_by_idx ON account_balance_snapshots (recorded_by);

CREATE TABLE IF NOT EXISTS recurring_items (
    id           uuid        PRIMARY KEY,
    household_id uuid        NOT NULL REFERENCES households (id) ON DELETE CASCADE,
    name         text        NOT NULL,
    kind         text        NOT NULL CHECK (kind IN ('bill', 'subscription', 'income')),
    amount_cents bigint      NOT NULL,
    category_id  uuid        NULL REFERENCES categories (id) ON DELETE SET NULL,
    account_id   uuid        NULL REFERENCES accounts (id) ON DELETE SET NULL,
    frequency    text        NOT NULL CHECK (frequency IN ('weekly', 'biweekly', 'monthly', 'quarterly', 'yearly', 'once')),
    anchor_date  date        NOT NULL,
    end_date     date        NULL,
    auto_pay     boolean     NOT NULL DEFAULT false,
    notes        text        NULL,
    url          text        NULL,
    created_by   uuid        NOT NULL REFERENCES users (id),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    archived_at  timestamptz NULL,
    CONSTRAINT recurring_items_end_after_anchor CHECK (end_date IS NULL OR end_date >= anchor_date)
);

CREATE INDEX IF NOT EXISTS recurring_items_household_id_idx     ON recurring_items (household_id);
CREATE INDEX IF NOT EXISTS recurring_items_household_active_idx ON recurring_items (household_id) WHERE archived_at IS NULL;
CREATE INDEX IF NOT EXISTS recurring_items_category_id_idx      ON recurring_items (category_id);
CREATE INDEX IF NOT EXISTS recurring_items_account_id_idx       ON recurring_items (account_id);
CREATE INDEX IF NOT EXISTS recurring_items_created_by_idx       ON recurring_items (created_by);

CREATE TABLE IF NOT EXISTS occurrence_payments (
    recurring_item_id uuid        NOT NULL REFERENCES recurring_items (id) ON DELETE CASCADE,
    due_date          date        NOT NULL,
    paid_at           timestamptz NOT NULL DEFAULT now(),
    paid_by           uuid        NOT NULL REFERENCES users (id),
    amount_cents      bigint      NOT NULL,
    PRIMARY KEY (recurring_item_id, due_date)
);

CREATE INDEX IF NOT EXISTS occurrence_payments_paid_by_idx ON occurrence_payments (paid_by);
